#!/bin/sh
# Generated by .claude/scripts/github/repo_script.py (Phase 11a, DEC-13). HUMAN-RUN ONLY, from a plain terminal.
# It prints every command and runs none of them unless you add --apply. Read it first: it is short on purpose.
#
#   sh .claude/bootstrap/setup.sh local  [--apply]    edits files in this checkout; you commit the result
#   sh .claude/bootstrap/setup.sh remote [--apply]    talks to GitHub: needs `gh auth login` done by you
#
# Parameters (checked when this file was generated):
#   repo            acme/widgets
#   create-repo     no
#   visibility      private
#   default-branch  main
#   variant         solo
#   approvers       (none)
#   labels          yes
#   boundary        no
#   workflows       (none)
#   config-plan     (none)
set -eu
if [ -n "${CLAUDECODE+x}" ] || [ -n "${CLAUDE_CODE_ENTRYPOINT+x}" ]; then
  echo "setup: refusing to run inside a Claude Code session (CLAUDECODE is set). Run it from a plain terminal." >&2
  exit 2
fi
PHASE="${1:-}"
APPLY=no
case "$PHASE" in local|remote) ;; *) echo "usage: sh $0 local|remote [--apply]" >&2; exit 2 ;; esac
shift
for arg in "$@"; do
  case "$arg" in
    --apply) APPLY=yes ;;
    *) echo "setup: unknown argument: $arg" >&2; exit 2 ;;
  esac
done
cd "$(dirname "$0")/../.."
[ -f .claude/scripts/github/labels.py ] || { echo "setup: run this from a repository that has the kit installed (.claude/scripts/github/)" >&2; exit 2; }

show() {
  printf '+'
  for a in "$@"; do
    case "$a" in
      ''|*[!A-Za-z0-9_./:=@%+,-]*) printf " '%s'" "$a" ;;
      *) printf ' %s' "$a" ;;
    esac
  done
  printf '\n'
}
step() { show "$@"; if [ "$APPLY" = yes ]; then "$@"; fi; }
# kit scripts are dry runs on their own; the flag that makes them act is added only with --apply
kit_apply() { show "$@"; if [ "$APPLY" = yes ]; then "$@" --apply; else "$@"; fi; }
kit_write() { show "$@"; if [ "$APPLY" = yes ]; then "$@" --write; else "$@"; fi; }
say() { printf '\n== %s\n' "$1"; }
if [ "$APPLY" = yes ]; then echo "setup $PHASE: APPLY"; else echo "setup $PHASE: DRY RUN (nothing runs; add --apply)"; fi

if [ "$PHASE" = local ]; then
  echo "Nothing to do in the local phase."
  echo "Now commit what changed (an H6 change goes through your normal review), then run the remote phase."
  exit 0
fi

say "1. labels (apply-labels.sh)"
kit_apply .claude/scripts/github/apply-labels.sh --repo acme/widgets

say "Still yours to do"
echo '  - create the bot identity: docs/security/bot-identity.md (this script never creates or scopes it)'
echo '  - CODEOWNERS: copy .claude/templates/security/CODEOWNERS.template to .github/CODEOWNERS, fill the placeholders, commit it through a pull request'
echo '  - secrets: if you use intake.yml or claude-review.yml, run `gh secret set ANTHROPIC_API_KEY --repo acme/widgets` yourself (it prompts; the key is never in a file)'
echo '  - variables: CLAUDE_CODE_VERSION (the version your canary passed), SMOKE_URL if you use smoke.yml'
echo '  - make the job `verify` a required status check in the ruleset (docs/security/rulesets.md)'
echo '  - then check it: .claude/scripts/github/verify-boundary.sh --repo acme/widgets --run'
